WITH lines AS (SELECT id, effective_from, EXPLODE_OUTER(discounts) AS tier_value FROM price_tiers), filtered AS (SELECT *, ROUND(tier_value * 1.15, 2) AS adjusted_tier_value FROM lines WHERE effective_from > DATE '2024-04-21'), metrics AS (SELECT *, DENSE_RANK() OVER (ORDER BY tier_value DESC NULLS FIRST) AS tier_value_dense_rank, CUME_DIST() OVER (ORDER BY adjusted_tier_value NULLS FIRST) AS adjusted_tier_value_cume_dist, DENSE_RANK() OVER (ORDER BY tier_value NULLS LAST) AS tier_value_dense_rank_2, PERCENT_RANK() OVER (ORDER BY adjusted_tier_value DESC NULLS LAST) AS adjusted_tier_value_percent_rank, CUME_DIST() OVER (ORDER BY adjusted_tier_value DESC NULLS FIRST) AS adjusted_tier_value_cume_dist_2 FROM filtered), with_windows AS (SELECT *, RANK() OVER (ORDER BY tier_value_dense_rank DESC NULLS FIRST) AS tier_value_dense_rank_rank, PERCENT_RANK() OVER (ORDER BY adjusted_tier_value_cume_dist_2 NULLS LAST) AS adjusted_tier_value_cume_dist_2_percent_rank, RANK() OVER (ORDER BY tier_value NULLS FIRST) AS tier_value_rank FROM metrics), metrics_price_tiers AS (SELECT *, RANK() OVER w_ordered AS tier_value_dense_rank_rank_rank, DENSE_RANK() OVER (ORDER BY adjusted_tier_value_cume_dist_2 DESC NULLS LAST) AS adjusted_tier_value_cume_dist_2_dense_rank FROM with_windows WINDOW w_ordered AS (ORDER BY tier_value_dense_rank_rank NULLS FIRST)), with_windows_price_tiers AS (SELECT id, effective_from, tier_value, adjusted_tier_value, tier_value_dense_rank, adjusted_tier_value_cume_dist, tier_value_dense_rank_2, adjusted_tier_value_percent_rank, adjusted_tier_value_cume_dist_2, tier_value_dense_rank_rank, adjusted_tier_value_cume_dist_2_percent_rank, tier_value_rank, tier_value_dense_rank_rank_rank, adjusted_tier_value_cume_dist_2_dense_rank, DENSE_RANK() OVER (ORDER BY adjusted_tier_value_percent_rank DESC) AS adjusted_tier_value_percent_rank_dense_rank, PERCENT_RANK() OVER (ORDER BY adjusted_tier_value DESC) AS adjusted_tier_value_percent_rank_2, CUME_DIST() OVER (ORDER BY adjusted_tier_value DESC NULLS FIRST) AS adjusted_tier_value_cume_dist_3 FROM metrics_price_tiers) SELECT id, effective_from, tier_value, adjusted_tier_value, tier_value_dense_rank, adjusted_tier_value_cume_dist, adjusted_tier_value_percent_rank, adjusted_tier_value_cume_dist_2_percent_rank, tier_value_dense_rank_rank_rank FROM with_windows_price_tiers ORDER BY adjusted_tier_value_cume_dist_2_percent_rank;
